"""StreamSOC — Streamlit dashboard for the AI-Agentic SOC triage engine.

Run from this folder::

    streamlit run app.py

The dashboard works in two modes:

* **Local reports** — reads the Markdown/HTML reports already generated by the
  agent. No Wazuh, API, database or LLM key required.
* **Triage API** — talks to the FastAPI control plane on 127.0.0.1:8080 so a
  new Wazuh alert can be queued for investigation.

``Auto`` uses the API when it is healthy and falls back to local reports.
"""

from __future__ import annotations

from pathlib import Path

import streamlit as st

from frontend.backends import (
    BackendError,
    LocalBackend,
    build_backend,
    default_api_url,
    default_paths,
)
from frontend.views import (
    inject_css,
    page_about,
    page_cases,
    page_evaluation,
    page_investigate,
    page_overview,
)


def main() -> None:
    st.set_page_config(
        page_title="StreamSOC — AI-Agentic SOC",
        page_icon=None,
        layout="wide",
        initial_sidebar_state="expanded",
    )
    inject_css()

    paths = default_paths()
    st.session_state.setdefault("analyst_name", "")

    with st.sidebar:
        st.markdown("## StreamSOC")
        st.caption("AI-Agentic SOC triage dashboard")

        source = st.radio(
            "Data source",
            ["Auto", "Local reports", "Triage API"],
            index=0,
            help="Auto uses the API when it is healthy and falls back to the report folder.",
        )
        api_url = st.text_input("Triage API URL", value=default_api_url())
        analyst_name = st.text_input(
            "Analyst name", value=st.session_state.get("analyst_name", "")
        )
        st.session_state["analyst_name"] = analyst_name

        if st.button("Refresh data", width="stretch"):
            st.rerun()

        st.divider()
        page = st.radio(
            "View",
            ["Overview", "Cases", "Investigate", "Evaluation", "About"],
            index=0,
        )

        st.divider()
        st.caption("Reports: %s" % paths["reports_dir"])

    backend = _build_backend(source, api_url, paths)

    try:
        health = backend.health()
        cases = backend.list_cases()
    except BackendError as exc:
        st.error("Backend error: %s" % exc)
        st.stop()

    with st.sidebar:
        if backend.mode == "api":
            st.success("Triage API: %s" % health.get("status", "ok"))
            st.caption(
                "Queued %s | Running %s | Cases %s"
                % (
                    health.get("queued_jobs", 0),
                    health.get("running_jobs", 0),
                    len(cases),
                )
            )
        else:
            st.info("Local report mode")
            st.caption(
                "No live API needed. %d report(s) loaded from disk." % len(cases)
            )

        if backend.mode == "api":
            try:
                jobs = backend.list_jobs(limit=5)
            except BackendError:
                jobs = []
            if jobs:
                st.caption("Recent jobs")
                for job in jobs:
                    st.caption(
                        "%s | %s | %s"
                        % (
                            job.get("status", "?"),
                            job.get("alert_id", "?"),
                            str(job.get("job_id", ""))[:8],
                        )
                    )

        st.divider()
        st.caption(
            "Human-in-the-loop only. The dashboard records decisions and never "
            "executes containment."
        )

    if page == "Overview":
        page_overview(backend, cases)
    elif page == "Cases":
        page_cases(backend, cases)
    elif page == "Investigate":
        page_investigate(backend)
    elif page == "Evaluation":
        page_evaluation(paths["evals_dir"])
    else:
        page_about(
            Path(__file__).resolve().parent / "ASSESSMENT.md",
            paths["docs_dir"] / "ARCHITECTURE.md",
        )


def _build_backend(source: str, api_url: str, paths: dict):
    try:
        return build_backend(
            source,
            api_url,
            paths["reports_dir"],
            paths["decisions_path"],
        )
    except BackendError as exc:
        st.sidebar.error("API unavailable: %s" % exc)
        st.sidebar.caption("Falling back to local report mode.")
        return LocalBackend(paths["reports_dir"], paths["decisions_path"])


if __name__ == "__main__":
    main()
